type TaskState = "todo" | "doing" | "done";
type TaskEvent = { type: "START" } | { type: "FINISH" };
function transition(state: TaskState, event: TaskEvent): TaskState {
  if (state === "todo" && event.type === "START") return "doing";
  if (state === "doing" && event.type === "FINISH") return "done";
  return state;
}
